                <div class="tw-text-center tw-relative tw-px-32">
                    <!-- Borders -->
                    <!-- Top -->
                    <div class="tw-h-2 tw-w-full tw-absolute tw-top-0 tw-left-0 tw-z-10" :style="`background: ${gradients.bronze.top}`"></div>
                    <!-- Right -->
                    <div class="tw-h-full tw-w-2 tw-absolute tw-top-0 tw-right-0 tw-z-10" :style="`background: ${gradients.bronze.right}`"></div>
                    <!-- Bottom -->
                    <div class="tw-h-2 tw-w-full tw-absolute tw-bottom-0 tw-left-0 tw-z-10" :style="`background: ${gradients.bronze.bottom}`"></div>
