        </div>
        <div class="tw-px-2 lg:tw-px-10">
            <img v-if="imageSrc" :src="imageSrc" class="tw-w-full tw-object-contain tw-mb-6" />
            <div class="tw-flex tw-justify-end">
                <MuButton @click="generatePdf">Download</MuButton>
            </div>
        </div>
    </InfoModal>
